<?php
session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{ttOperationsRequireCsrf();$pdo->beginTransaction();$industryId=(int)($_POST['current_industry_id']??0);$track=substr(trim((string)($_POST['current_track']??'')),0,120);$name=substr(trim((string)($_POST['name']??'')),0,120);$carIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['car_ids']??[])))));if($name===''||$industryId<=0||$track===''||!$carIds)throw new RuntimeException('Name, location, track, and at least one car are required.');$checkIndustry=$pdo->prepare('SELECT id FROM industries WHERE id=? AND railroad_id=?');$checkIndustry->execute([$industryId,$railroadId]);if(!$checkIndustry->fetchColumn())throw new RuntimeException('Invalid location.');$reserved=ttReservedEquipmentIds($pdo,$railroadId);$number=ttNextScopedNumber($pdo,'prepared_cuts','cut_number',$railroadId,'CUT-',5);$stmt=$pdo->prepare('INSERT INTO prepared_cuts(railroad_id,cut_number,name,current_industry_id,current_track,intended_job_template_id,notes) VALUES(?,?,?,?,?,?,?)');$stmt->execute([$railroadId,$number,$name,$industryId,$track,($job=(int)($_POST['intended_job_template_id']??0))?:null,substr(trim((string)($_POST['notes']??'')),0,5000)]);$cutId=(int)$pdo->lastInsertId();$verify=$pdo->prepare("SELECT e.id FROM equipment e WHERE e.id=? AND e.railroad_id=? AND e.active=1 AND e.current_industry_id=? AND COALESCE(e.current_track,'')=? AND COALESCE(e.equipment_class,'')<>'Locomotive' AND NOT EXISTS(SELECT 1 FROM prepared_cut_cars pc JOIN prepared_cuts c ON c.id=pc.prepared_cut_id WHERE pc.equipment_id=e.id AND c.status IN('ready','assigned','in_use')) FOR UPDATE");$insert=$pdo->prepare('INSERT INTO prepared_cut_cars(prepared_cut_id,equipment_id,position) VALUES(?,?,?)');$position=1;foreach($carIds as $carId){if(in_array($carId,$reserved,true))throw new RuntimeException('A selected car is reserved by an active assignment.');$verify->execute([$carId,$railroadId,$industryId,$track]);if(!$verify->fetchColumn())throw new RuntimeException('Every selected car must still be active, unreserved, and physically at the selected location and track.');$insert->execute([$cutId,$carId,$position++]);}$pdo->commit();header('Location: prepared_cut.php?id='.$cutId);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$stmt=$pdo->prepare("SELECT c.*,i.industry_name,j.job_name,COUNT(pc.equipment_id) car_count FROM prepared_cuts c JOIN industries i ON i.id=c.current_industry_id LEFT JOIN jobs j ON j.id=c.intended_job_template_id LEFT JOIN prepared_cut_cars pc ON pc.prepared_cut_id=c.id WHERE c.railroad_id=? GROUP BY c.id ORDER BY FIELD(c.status,'ready','assigned','in_use','released','dissolved'),c.id DESC");$stmt->execute([$railroadId]);$cuts=$stmt->fetchAll(PDO::FETCH_ASSOC);$industries=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? ORDER BY industry_name');$industries->execute([$railroadId]);$industries=$industries->fetchAll(PDO::FETCH_ASSOC);$jobs=$pdo->prepare('SELECT id,job_name FROM jobs WHERE railroad_id=? AND active=1 ORDER BY job_name');$jobs->execute([$railroadId]);$jobs=$jobs->fetchAll(PDO::FETCH_ASSOC);$cars=$pdo->prepare("SELECT e.id,e.reporting_marks,e.road_number,e.equipment_type,e.load_status,e.operations_service,e.current_industry_id,e.current_track,e.photo_filename,i.industry_name FROM equipment e JOIN industries i ON i.id=e.current_industry_id WHERE e.railroad_id=? AND e.active=1 AND COALESCE(e.equipment_class,'')<>'Locomotive' AND NOT EXISTS(SELECT 1 FROM prepared_cut_cars pc JOIN prepared_cuts c ON c.id=pc.prepared_cut_id WHERE pc.equipment_id=e.id AND c.status IN('ready','assigned','in_use')) ORDER BY i.industry_name,e.current_track,e.reporting_marks,e.road_number");$cars->execute([$railroadId]);$cars=$cars->fetchAll(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Prepared Cuts</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex justify-content-between align-items-end gap-3 mb-4"><div><p class="tt-eyebrow">Operations</p><h1>Prepared Trains &amp; Cuts</h1><p class="text-muted">Saved physical groups of cars. Grouping or dissolving a cut never moves equipment.</p></div><button class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#newCut">Create Prepared Cut</button></div><?php if($error):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?>
<div class="collapse mb-4" id="newCut"><div class="card card-body"><form method="post" id="cutForm" class="row g-3"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" maxlength="120" required></div><div class="col-md-6"><label class="form-label">Intended Job Title <span class="text-muted">(optional)</span></label><select class="form-select" name="intended_job_template_id"><option value="">None</option><?php foreach($jobs as $job):?><option value="<?=(int)$job['id']?>"><?=ttHtml($job['job_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Current Location</label><select class="form-select" name="current_industry_id" id="cutLocation" required><option value="">Choose…</option><?php foreach($industries as $industry):?><option value="<?=(int)$industry['id']?>"><?=ttHtml($industry['industry_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Current Track</label><input class="form-control" name="current_track" id="cutTrack" list="cutTracks" required><datalist id="cutTracks"><?php foreach(array_unique(array_filter(array_column($cars,'current_track'))) as $track):?><option value="<?=ttHtml($track)?>"><?php endforeach;?></datalist></div><div class="col-12"><label class="form-label">Cars <span class="text-muted">(order follows the list; no fixed size)</span></label><div class="tt-car-picker"><?php foreach($cars as $car):?><label class="tt-car-choice" data-location="<?=(int)$car['current_industry_id']?>" data-track="<?=ttHtml(strtolower(trim((string)$car['current_track'])))?>"><input type="checkbox" name="car_ids[]" value="<?=(int)$car['id']?>"><?php if($url=ttPhotoUrl($car['photo_filename'])):?><img src="<?=ttHtml($url)?>" alt=""><?php else:?><span class="tt-no-photo">No Photo</span><?php endif;?><span><strong><?=ttHtml(trim($car['reporting_marks'].' '.$car['road_number']))?></strong><small><?=ttHtml($car['equipment_type'].' · '.$car['load_status'].' · '.$car['operations_service'].' · '.$car['industry_name'].' / '.$car['current_track'])?></small></span></label><?php endforeach;?></div></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div><div><button class="btn btn-success">Save Ready Cut</button></div></form></div></div>
<div class="tt-assignment-grid"><?php foreach($cuts as $cut):?><article class="tt-assignment-card"><div class="d-flex justify-content-between"><div><p class="tt-eyebrow mb-1"><?=ttHtml($cut['cut_number'])?></p><h3><?=ttHtml($cut['name'])?></h3></div><span class="badge tt-status-<?=ttHtml($cut['status'])?>"><?=ttHtml(ucwords($cut['status']))?></span></div><p><?=ttHtml($cut['industry_name'].' / '.$cut['current_track'])?><br><strong><?=(int)$cut['car_count']?> cars</strong><?= $cut['job_name']?'<br>For '.ttHtml($cut['job_name']):''?></p><a class="btn btn-sm btn-outline-primary" href="prepared_cut.php?id=<?=(int)$cut['id']?>">View / Manage</a></article><?php endforeach;?></div></section></div><script>const loc=document.getElementById('cutLocation'),track=document.getElementById('cutTrack');function filterCars(){const l=loc.value,t=track.value.trim().toLowerCase();document.querySelectorAll('.tt-car-choice').forEach(x=>{const show=(!l||x.dataset.location===l)&&(!t||x.dataset.track===t);x.hidden=!show;if(!show)x.querySelector('input').checked=false;});}loc.addEventListener('change',filterCars);track.addEventListener('input',filterCars);</script><?php include '../includes/footer.php';?>
